with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('gå agurk', 'phrase', '9cb86693-bd4c-5425-bdc3-019f19815935', 1, 'verb', null, 'go crazy', 'Min gamle computer gik agurk i går.', 'My old computer went crazy yesterday.'), ('gå itu', 'phrase', 'ef2d9a0b-06f3-5bd1-9af9-326f5843b457', 1, 'verb', null, 'to break (into pieces)', 'Min telefon gik itu, da jeg tabte den på gulvet.', 'My phone broke when I dropped it on the floor.'), ('ombestemme sig', 'phrase', '4a9627c8-cec7-570e-a689-93cccfb9ad50', 1, 'verb', null, 'to change one''s mind', 'Jeg tror, at han ombestemmer sig i morgen.', 'I think he will change his mind tomorrow.'), ('slå plat og krone', 'phrase', '95d4ca0e-cc3d-501e-be8a-5531d1e03419', 1, 'verb', null, 'to flip a coin (to decide something)', 'Vi slog plat og krone om den sidste kage.', 'We tossed a coin for the last cake.'), ('gå for sig', 'phrase', '6b919881-6e45-5ee1-aa2b-f0c189cabae8', 1, 'verb', null, 'to happen', 'Mødet gik for sig i kantinen.', 'The meeting took place in the canteen.'), ('gøre godt', 'phrase', '2810693d-fd4f-539a-81ec-6452e84e3835', 1, 'verb', null, 'to do good', 'Motion gør godt for helbredet.', 'Exercise is good for health.'), ('se sig for', 'phrase', '24e790b4-1e18-5894-9c32-d785a3563645', 1, 'verb', null, 'to look out (be careful)', 'Du skal se dig for, når du går over gaden.', 'You have to watch out when you cross the street.'), ('se sig om', 'phrase', '05d1af47-17eb-5651-8fb3-dd720b093467', 1, 'verb', null, 'to look around', 'Hun ser sig om i det nye hus.', 'She looks around the new house.'), ('se op', 'phrase', '8b368b3a-537a-5412-8720-f29b2b878ae1', 1, 'verb', null, 'to look up', 'Hun ser op mod himlen.', 'She looks up at the sky.'), ('se op til', 'phrase', '90ccf80c-2d6c-5aeb-8527-ea952ad80efc', 1, 'verb', null, 'to look up to (someone)', 'Mange børn ser op til deres forældre.', 'Many children look up to their parents.'), ('tage for sig', 'phrase', '99883457-5da0-5256-ac56-e6a34d99b5b0', 1, 'verb', null, 'to help oneself (to food)', 'Tag for dig af salaten, der er nok.', 'Help yourself to the salad, there is enough.'), ('tage over', 'phrase', '6a777937-db71-56ad-b196-08acafce9bba', 1, 'verb', null, 'to take over (control, responsibility)', 'Hun tager over, når chefen er syg.', 'She takes over when the boss is ill.'), ('tage sig for', 'phrase', '82e28e56-784f-563b-b60c-24ce93dab675', 1, 'verb', null, 'to occupy oneself (with something)', 'Hvad vil du tage dig for i weekenden?', 'What are you going to do this weekend?'), ('blive stående', 'phrase', '68610d24-abc2-501f-a93a-e8aa7a6bf831', 1, 'verb', null, 'to remain standing', 'Han blev stående ved døren i lang tid.', 'He remained standing at the door for a long time.'), ('stå godt til', 'phrase', '0e429d81-495c-51dc-a6c6-3f332f244f3e', 1, 'verb', null, 'to be going well (of affairs, relationships)', 'Det står godt til med deres ægteskab.', 'Their marriage is doing well.'), ('sige sig selv', 'phrase', '05c59836-9e5f-5a5d-b793-ef97817c7827', 1, 'verb', null, 'to be obvious', 'Det siger sig selv, at børn har brug for kærlighed.', 'It goes without saying that children need love.'), ('være lige ved at', 'phrase', '8a2af559-f4f7-5811-be3c-0c3143b61850', 1, 'verb', null, 'to be on the verge of', 'Jeg var lige ved at falde på isen.', 'I almost fell on the ice.'), ('gøre brug af', 'phrase', 'dea966c5-d759-5956-8af0-dfc46bd6e2b7', 1, 'verb', null, 'to use', 'Hun gør brug af sin erfaring i det nye job.', 'She makes use of her experience in her new job.'), ('dele sig op', 'phrase', '2e0e0abe-61d5-5e0c-9af1-73b5701c1248', 1, 'verb', null, 'to split up (into groups)', 'Eleverne deler sig op i mindre grupper til projektarbejde.', 'The pupils split up into smaller groups for project work.'), ('holde til', 'phrase', '375a0d0e-8c6c-5ec7-8fb5-84f405832a47', 1, 'verb', null, 'to be located, to hang out', 'Mange unge holder til i parken om sommeren.', 'Many young people spend time in the park in the summer.'), ('holde til', 'phrase', '6548b6c7-d0a6-573a-9718-90e2ef6d331a', 2, 'verb', null, 'to endure, to put up with', 'Jeg kan ikke holde til al den støj længere.', 'I can''t stand all that noise anymore.'), ('holde ved', 'phrase', 'b94ff8ae-da70-5c34-8d4e-114cba7872d9', 1, 'verb', null, 'to keep going (with something)', 'Hun holdt ved med at øve sig hver dag.', 'She kept practicing every day.'), ('blive et nyt menneske', 'phrase', 'f63beced-6a8f-529c-b5a9-e3941241e3fc', 1, 'verb', null, 'to become a new person (change for the better)', 'Efter rejsen føler jeg, at jeg er blevet et nyt menneske.', 'After the trip, I feel like I''ve become a new person.'), ('se sig tilbage', 'phrase', 'f842ed24-2bc2-5369-8cf8-dd622df3834a', 1, 'verb', null, 'to look back (over one''s shoulder)', 'Hun så sig tilbage, før hun gik ind i huset.', 'She looked back before entering the house.'), ('veje op', 'phrase', 'ef6e0707-f394-52e5-861f-c5be1c64ea36', 1, 'verb', null, 'to compensate (for a shortcoming)', 'Hans erfaring vejer op for den manglende uddannelse.', 'His experience makes up for the lack of education.'), ('skrive ned', 'phrase', '34c8e248-f056-5531-8585-d4cd942275a1', 1, 'verb', null, 'to write down', 'Jeg skrev ned hvad læreren sagde.', 'I wrote down what the teacher said.'), ('komme til penge', 'phrase', 'a120794d-39b0-5cfd-a72e-f3d4c3c992a2', 1, 'verb', null, 'to come into money', 'Han kom til penge, da hans onkel døde.', 'He came into money when his uncle died.'), ('klare den', 'phrase', '0eed097d-a0d8-52bd-895d-ea8476392839', 1, 'verb', null, 'to manage', 'Jeg tror, hun klarer den uden hjælp.', 'I think she can handle it without help.'), ('klare op', 'phrase', '9232b613-c539-5016-8c04-a06ab9988cf2', 1, 'verb', null, 'to clear up (weather)', 'Det regner nu, men det klarer op senere.', 'It is raining now, but it will clear up later.'), ('være tro mod', 'phrase', '5c833509-a1b3-5d0e-9862-98457a8845fe', 1, 'verb', null, 'to be loyal to', 'Han er tro mod sine venner.', 'He is faithful to his friends.'), ('lægge sig ned', 'phrase', 'c1713ff9-4d31-591e-80b2-f5803e6024c2', 1, 'verb', null, 'to lie down', 'Jeg lægger mig ned på sofaen efter arbejde.', 'I lie down on the couch after work.'), ('begynde med at', 'phrase', '67e53252-5fb9-59cb-9e19-7789aaa9ae28', 1, 'verb', null, 'to start by', 'Jeg begynder med at tage opvasken.', 'I start by doing the dishes.'), ('gå på grund', 'phrase', '46599fb2-34d5-5221-8647-0e8d5e3698c6', 1, 'verb', null, 'to run aground (of a ship)', 'Skibet gik på grund nær havnen.', 'The ship ran aground near the harbour.'), ('på grund af at', 'phrase', 'a229d558-8ab9-594a-b83f-6e2b452ce05f', 1, 'adverb', null, 'because', 'Vi blev hjemme på grund af at det regnede.', 'We stayed at home because it was raining.'), ('gøre kål på', 'phrase', '52898bb9-23db-5b67-9111-2155f21292e6', 1, 'verb', null, 'to finish off (something)', 'Vi gjorde kål på resterne fra i går.', 'We finished off yesterday''s leftovers.'), ('gå sammen', 'phrase', 'eb9af950-d090-5ce5-bd1b-7df1d4c0b7cf', 1, 'verb', null, 'to join forces', 'De to virksomheder gik sammen om et nyt projekt.', 'The two companies joined forces on a new project.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0011' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
